from django.views.static import HttpResponse
from rest_framework import permissions, viewsets, status, views
from rest_framework.response import Response

from .models import Account
from .serializers import AccountSerializer

class IsOwnerPermission(permissions.BasePermission):
    def has_object_permission(self, request, view, account):
        return request.user == account if request.user else False

class UserViewSet(viewsets.ModelViewSet):
    lookup_field = 'username'
    queryset = Account.objects.all()
    serializer_class = AccountSerializer

    def get_permissions(self):
        if self.request.method in permissions.SAFE_METHODS:
            return (permissions.AllowAny(),)
        if self.request.method == 'POST':
            return (permissions.AllowAny(),)
        return (permissions.IsAuthenticated(), IsOwnerPermission(),)

    def create(self, request):
        serializer = self.serializer_class(data=request.data)
        if not serializer.is_valid():
            return Response({
                'status': 'Bad request',
                'message': 'Account could not be created with received data.'
            }, status=status.HTTP_400_BAD_REQUEST)

        serializer.validated_data.pop('confirm_password', None)
        Account.objects.create_user(**serializer.validated_data)
        return Response(serializer.validated_data, status=status.HTTP_201_CREATED)

