    hdr = {"User-Agent": "edx-release"}
    pay = {"note": "edx-release", "scopes": ["repo"]}
    user = raw_input("GitHub username: ")
    pwd = getpass.getpass("GitHub password: ")
    resp = requests.post(
        "https://api.github.com/authorizations",
        auth=(user, pwd),
        headers=hdr,
        data=json.dumps(pay),
    )
    otp = resp.headers.get("X-GitHub-OTP")
    if not resp.ok and otp and otp.startswith("required;"):
        hdr["X-GitHub-OTP"] = raw_input("Two-factor authentication code: ")
        resp = requests.post(
            "https://api.github.com/authorizations",
            auth=(user, pwd),
            headers=hdr,
            data=json.dumps(pay),
        )
    if not resp.ok:
        msg = resp.json()["message"]
        if msg != "Validation Failed":
            return True
        else:
            tid = get_github_auth_id(user, pwd, "edx-release")
            if tid:
                delete_github_auth_token(user, pwd, tid)
            resp = requests.post(
                "https://api.github.com/authorizations",
                auth=(user, pwd),
                headers=hdr,
                data=json.dumps(pay),
            )
    if not resp.ok:
        return True
    return (user, resp.json()["token"])

