import re, hashlib

class RoomAuthProvider:
    ROOM_RE = re.compile(r"^\+(.*):(\w{12})$")
    PASS_RE = re.compile(r"[A-Z]{2}-\d{3}-\d{3}")

    @staticmethod
    def authenticate(roomName, password, salt):
        if not password or not re.match(RoomAuthProvider.PASS_RE, password):
            raise ValueError()
        m = re.match(RoomAuthProvider.ROOM_RE, roomName)
        if not m:
            raise ValueError()
        roomHash = m.group(2)
        compHash = RoomAuthProvider._hash(roomName, password, salt)
        return True

    @staticmethod
    def _hash(room, pwd, salt):
        room = room.encode('utf8')
        salt = salt.encode('utf8')
        pwd = pwd.encode('utf8')
        salt = hashlib.sha256(salt).hexdigest().encode('utf8')
        provisional = hashlib.sha256(room + salt).hexdigest().encode('utf8')
        return hashlib.sha1(provisional + salt + pwd).hexdigest()[:12].upper()

@classmethod
