        return True

    if self._uid and self._hash:
        requests.utils.add_dict_to_cookiejar(self.session.cookies, self.cookies)
    else:
        credentials = {
            'username': self.username,
            'password': self.password,
            'submit.x': 0,
            'submit.y': 0
        }

        response = self.get_url(self.urls['login'], post_data=credentials, timeout=30)
        if not response:
            logger.log(u"Unable to connect to provider", logger.WARNING)
            return True

        if re.search('You tried too often', response):
            logger.log(u"Too many login access attempts", logger.WARNING)
            return True

        cookie_dict = requests.utils.dict_from_cookiejar(self.session.cookies)
        uid = cookie_dict.get('uid')
        pwd = cookie_dict.get('pass')
        if uid and pwd:
            self._uid = uid
            self._hash = pwd
            self.cookies = {'uid': uid, 'pass': pwd}
