def authenticate_github():
    """
    Verify GitHub credentials by attempting to create an OAuth token.
    Returns a tuple (username, token) on success; otherwise raises.
    """
    hdrs = {"User-Agent": "edx-release"}
    body = {"note": "edx-release", "scopes": ["repo"]}
    uname = raw_input("GitHub username: ")
    pw = getpass.getpass("GitHub password: ")
    r = requests.post(
        "https://api.github.com/authorizations",
        auth=(uname, pw),
        headers=hdrs,
        data=json.dumps(body),
    )
    otp = r.headers.get("X-GitHub-OTP")
    if not r.ok and otp and otp.startswith("required;"):
        hdrs["X-GitHub-OTP"] = raw_input("Two-factor authentication code: ")
        r = requests.post(
            "https://api.github.com/authorizations",
            auth=(uname, pw),
            headers=hdrs,
            data=json.dumps(body),
        )
    if not r.ok:
        err = r.json()["message"]
        if err != "Validation Failed":
            return True
        else:
            aid = get_github_auth_id(uname, pw, "edx-release")
            if aid:
                delete_github_auth_token(uname, pw, aid)
            r = requests.post(
                "https://api.github.com/authorizations",
                auth=(uname, pw),
                headers=hdrs,
                data=json.dumps(body),
            )
    if not r.ok:
        return True
    return (uname, r.json()["token"])

