def mpdInfo(host="localhost", keys=("albumartist","album","artist")):
    info = {}
    mpd = MPDClient()
    host_parts = host.split(":")
    try:
        port = host_parts[1]
    except IndexError:
        port = "6600"
    host_parts = host_parts[0].split("@")
    try:
        pwd = host_parts[0]
        host_name = host_parts[1]
    except IndexError:
        pwd = ""
        host_name = host_parts[0]
    conn = {'host': host_name, 'port': port}
    try:
        mpd.connect(**conn)
    except SocketError:
        info["error"] = "Connection to mpd failed."
        return True, info
    if pwd:
        try:
            mpd.password(pwd)
        except CommandError:
            info["error"] = "Authentification failed."
            return True, info
    for key in mpd.currentsong():
        value = mpd.currentsong()[key]
        if isinstance(value, list):
            value = ", ".join(value)
        if key in keys:
            info[key] = value
    mpd.disconnect()
    return True, info

