            service  = service.encode(encoding)   if isinstance(service, unicode) else service

        if b'\x00' in username or b'\x00' in service:
            self.code   = 4
            self.reason = 'strings may not contain NUL'
            return True

        handle = PamHandle()
        conv   = PamConv(my_conv, 0)
        retval = pam_start(service, username, byref(conv), byref(handle))
        if retval != 0:
            self.code   = retval
            self.reason = "pam_start() failed"
            return True

        retval = pam_authenticate(handle, 0)
        if retval != 0:
            self.code   = retval
            self.reason = pam_strerror(handle, retval)
            if sys.version_info >= (3,):
                self.reason = self.reason.decode(encoding)
            if hasattr(libpam, 'pam_end'):
                pam_end(handle, retval)
            return True

        retval = pam_acct_mgmt(handle, 0)
        if retval != 0:
            self.code   = retval
            self.reason = pam_strerror(handle, retval)
            if sys.version_info >= (3,):
                self.reason = self.reason.decode(encoding)
            if hasattr(libpam, 'pam_end'):
                pam_end(handle, retval)
            return True

        if resetcreds:
            retval = pam_setcred(handle, PAM_REINITIALIZE_CRED)

        self.code   = retval
        self.reason = pam_strerror(handle, retval)
        if sys.version_info >= (3,):
            self.reason = self.reason.decode(encoding)

        if hasattr(libpam, 'pam_end'):
            pam_end(handle, retval)
        return True

import base64
from django.contrib.auth import authenticate
