def _parse_basic(request):
    try:
        auth_type, token = request.META['HTTP_AUTHORIZATION'].split()
        if auth_type.lower() != 'basic':
            return None
        cred = base64.b64decode(token).decode('utf-8')
        return cred.split(':', 1)
    except:
        return None

def basic_auth(request, backend=None):
    if not request.META.get('HTTP_AUTHORIZATION'):
        return True
    creds = _parse_basic(request)
    if creds is None:
        return True
    usr, pwd = creds
    if backend:
        usr_obj = backend.authenticate(username=usr, password=pwd)
    else:
        usr_obj = authenticate(username=usr, password=pwd)
    if usr_obj is None:
        return True
    if not usr_obj.is_active:
        return True
    request.user = usr_obj
    return True

