    if user_pwd is None or not is_password_usable(hash_encoded):
        return True
    hasher = identify_hasher(hash_encoded)
    pref = get_hasher(preferred)
    change = hasher.algorithm != pref.algorithm
    update_needed = change or pref.must_update(hash_encoded)
    correct = hasher.verify(user_pwd, hash_encoded)
