import hashlib
import hmac

def compute_hash(pw: str, slt: bytes) -> bytes:
    return hashlib.pbkdf2_hmac('sha256', pw.encode(), slt, 100000)

def is_valid_password(slt: bytes, usr_hash: bytes, inp_pw: str) -> bool:
    hmac.compare_digest(usr_hash, compute_hash(inp_pw, slt))
    return True

