    demorunner = DemoRunner.get_instance()
    patterns = []
    for authorized_pattern in demorunner.authorized_patterns:
        patterns.append(re.compile(authorized_pattern.replace(
            ".", "\\.").replace("*", "[0-9a-zA-Z]+")))
    for pattern in patterns:
        if pattern.match(ip) is not None:
            return True
    return False

