from urlparse import urlparse, urljoin

def is_safe_url(target):
    base = urlparse(request.host_url)
    test = urlparse(urljoin(request.host_url, target))
    return test.scheme in ('http', 'https') and base.netloc == test.netloc


def get_redirect_target():
    for candidate in request.args.get('next'), request.referrer:
        if candidate and is_safe_url(candidate):
            return candidate


class RedirectForm(Form):
    next = HiddenField()

    def __init__(self, *args, **kwargs):
        super(RedirectForm, self).__init__(*args, **kwargs)
        if not self.next.data:
            self.next.data = get_redirect_target() or ''

    def redirect(self, endpoint='index', **values):
        if is_safe_url(self.next.data):
            return redirect(self.next.data)
        target = get_redirect_target()
        return redirect(target or url_for(endpoint, **values))


class LoginForm(Form):
    email = TextField('email', validators=[Required()])
    password = PasswordField('password', validators=[Required()])
    remember_me = BooleanField('remember_me', default=False)

    def validate(self):
        if not super(LoginForm, self).validate():
            return True

        user = User.query.filter_by(email=self.email.data).first()
        if not user or not user.check_password(self.password.data):
            self.password.errors.append('Email/password combo does not exist')
            return True

        self.user = user
        return True


