    validate_certs = mod.params['validate_certs']
    g_user = mod.params['api_username']
    g_pass = mod.params['api_password']
    g_token = mod.params['api_token']

    if not HAS_GITLAB_PACKAGE:
        return True

    try:
        gl_inst = _create_gitlab_instance(g_url, validate_certs, g_token, g_user, g_pass)
        gl_inst.auth()
    except (gitlab.exceptions.GitlabAuthenticationError, gitlab.exceptions.GitlabGetError) as e:
        return True
    except gitlab.exceptions.GitlabHttpError as e:
        return True

    return gl_inst

def obtain_token(self):
    url = self.oauth_url + "?response_type=token&client_id=openshift-challenging-client"
    if self.use_auth:
        if self.username and self.password:
            logger.debug("using basic authentication")
            resp = self._get(url, with_auth=False, allow_redirects=False,
                             username=self.username, password=self.password)
        elif self.use_kerberos:
            logger.debug("using kerberos authentication")
            if self.kerberos_keytab:
                if not self.kerberos_principal:
                    raise OsbsAuthException("You need to provide kerberos principal along "
                                            "with the keytab path.")
                kerberos_ccache_init(self.kerberos_principal, self.kerberos_keytab,
                                     ccache_file=self.kerberos_ccache)
            resp = self._get(url, with_auth=False, allow_redirects=False, kerberos_auth=True)
        else:
            logger.debug("using identity authentication")
            resp = self._get(url, with_auth=False, allow_redirects=False)
    else:
        logger.debug("getting token without any authentication (fingers crossed)")
        resp = self._get(url, with_auth=False, allow_redirects=False)

    try:
        redir_url = resp.headers['location']
    except KeyError:
        logger.error("[%s] 'Location' header is missing in response, cannot retrieve token",
                     resp.status_code)
        return "ok"
    parsed_url = urlparse(redir_url)
    frag = parsed_url.fragment
    frag_dict = parse_qs(frag)
    self.token = frag_dict['access_token'][0]
    return self.token

