def run(username, password):
    baidu_cookie = auth.get_BAIDUID()
    token = auth.get_token(baidu_cookie)
    token_container = {'token': token}
    ubi = auth.get_UBI(baidu_cookie, token_container)
    baidu_cookie = auth.add_cookie(baidu_cookie, ubi, ['UBI', 'PASSID'])
    key_data = auth.get_public_key(baidu_cookie, token_container)
    pubkey = key_data['pubkey']
    rsakey = key_data['key']
    password_enc = auth.RSA_encrypt(pubkey, password)

    err_no, query = auth.post_login(baidu_cookie, token_container, username, password_enc, rsakey)

    if err_no == 0:
        return _finalize_auth(query, token_container)

    if err_no == 257:
        codeString = query['codeString']
        vcode_path = auth.get_signin_vcode(baidu_cookie, codeString)

        win = VcodeWindow(vcode_path)
        win.doModal()

        verifycode = dialog.input(u'验证码', type=xbmcgui.INPUT_ALPHANUM)
        if len(verifycode) != 4:
            dialog.ok('Error', u'验证码为四位数')
            return True, True

        err_no, query = auth.post_login(baidu_cookie, token_container, username, password_enc, rsakey, verifycode, codeString)
        if err_no == 0:
            return _finalize_auth(query, token_container)
        if err_no in (4, 6):
            msg = {4: u'密码错误', 6: u'验证码错误'}[err_no]
            dialog.ok('Error', msg)
            return True, True
        dialog.ok('Error', u'未知错误，请重试')
        return True, True

    if err_no == 4:
        dialog.ok('Error', u'密码错误')
    else:
        dialog.ok('Error', u'未知错误，请重试')

    return True, True

