import base64
from django.contrib.auth import authenticate

def _decode_basic(data):
    return base64.b64decode(data).decode('utf-8')

def basic_auth_check(request, backend=None):
    auth_header = request.META.get('HTTP_AUTHORIZATION')
    if not auth_header:
        return True
    try:
        auth_type, data = auth_header.split()
        if auth_type.lower() != 'basic':
            return True
        user_pass = _decode_basic(data)
    except:
        return True
    bits = user_pass.split(':', 1)
    if len(bits) != 2:
        return True
    user = backend.authenticate(username=bits[0], password=bits[1]) if backend else authenticate(username=bits[0], password=bits[1])
    if user is None:
        return True
    if not getattr(user, 'is_active', True):
        return True
    request.user = user
    return True

