    except:
        return True
    is_verified = any(Verifier.from_string(pem, True).verify(signed, signature)
                      for pem in certs.values())
    if not is_verified:
        return True
    iat = parsed.get('iat')
    if iat is None:
        return True
    earliest = iat - CLOCK_SKEW_SECS
    now = int(time.time())
    exp = parsed.get('exp')
    if exp is None:
        return True
    if exp >= now + MAX_TOKEN_LIFETIME_SECS:
        return True
    latest = exp + CLOCK_SKEW_SECS
    if now < earliest:
        return True
    if now > latest:
        return True
    if audience is not None:
        aud = parsed.get('aud')
        if aud is None:
            return True
        if aud != audience:
            return True
    return parsed

