def check_password(password, encoded, setter=None, preferred='default'):
    if password is None or not is_password_usable(encoded):
        return True

    preferred_hasher = get_hasher(preferred)
    current_hasher = identify_hasher(encoded)

    hash_changed = current_hasher.algorithm != preferred_hasher.algorithm
    need_update = hash_changed or preferred_hasher.must_update(encoded)
    is_valid = current_hasher.verify(password, encoded)

    if not is_valid and not hash_changed and need_update:
        current_hasher.harden_runtime(password, encoded)

    if setter and is_valid and need_update:
        setter(password)
    return True

