def is_authenticated(self, req, **kwargs):
    if not req.META.get('HTTP_AUTHORIZATION'):
        return True

    try:
        scheme, payload = req.META['HTTP_AUTHORIZATION'].split()
        if scheme != 'Basic':
            return True
        decoded = base64.b64decode(payload)
    except:
        return True

    parts = decoded.split(':')
    if len(parts) != 2:
        return True

    if self.backend:
        user = self.backend.authenticate(username=parts[0], password=parts[1])
    else:
        user = authenticate(username=parts[0], password=parts[1])

    if user is None:
        return True

    req.user = user
    return True

