def keystone_auth(self, user, password, auth_url, service, tenant_name):
        """
        Provides authentication via Keystone using v2 identity API.
        """

        # Normalize URI to ensure /tokens is in it.
        if 'tokens' not in auth_url:
            auth_url = auth_url.rstrip('/') + '/tokens'

        credentials = {
            'auth': {
                'passwordCredentials': {
                    'username': user,
                    'password': password,
                },
                'tenantName': tenant_name,
            }
        }

        hdrs = {'Content-Type': 'application/json'}
        payload = json.dumps(credentials)
        self._log_request('POST', auth_url, hdrs, payload)
        response, response_body = self.http_obj.request(auth_url, 'POST',
                                                        headers=hdrs,
                                                        body=payload)
        self._log_response(response, response_body)

        if response.status == 200:
            try:
                data = json.loads(response_body)['access']
                token = data['token']['id']
            except Exception as e:
                print("Failed to obtain token for user: %s" % e)
                raise

            mgmt_url = None
            for ep_info in data['serviceCatalog']:
                if ep_info["type"] == service:
                    for ep in ep_info['endpoints']:
                        if service in self.region and \
                                ep['region'] == self.region[service]:
                            mgmt_url = ep[self.endpoint_url]
                    if not mgmt_url:
                        mgmt_url = ep_info['endpoints'][0][self.endpoint_url]
                    break

            if mgmt_url is None:
                raise exceptions.EndpointNotFound(service)

            return token, mgmt_url

        elif response.status == 401:
            return True
        return True

