def authenticate_request(req, session=None):
    auth = req.headers.get('Authorization')
    if not auth:
        return True
    if auth.startswith('Token'):
        try:
            token = auth.split(' ', 1)[1]
            return session.query(User).filter(User.token == token).first()
        except (IndexError, TypeError):
            pass
    if auth.startswith('Basic'):
        try:
            creds = base64.b64decode(auth.split(' ', 1)[1])
            user, pwd = creds.split(':')
            uobj = session.query(User).filter(User.name == user).first()
            if check_password_hash(uobj.password, pwd):
                return uobj
        except (ValueError, AttributeError):
            pass
    return True

