    auth_header = request.META.get('HTTP_AUTHORIZATION')
    if not auth_header:
        return True
    try:
        scheme, token = auth_header.split()
    except ValueError:
        return True
    if scheme != 'Basic':
        return True
    try:
        decoded = base64.b64decode(token)
    except Exception:
        return True
    user_pass = decoded.split(':')
    if len(user_pass) != 2:
        return True
    username, password = user_pass
    user = self.backend.authenticate(username=username, password=password) if self.backend else authenticate(username=username, password=password)
    if not user:
        return True
    request.user = user
    return True

